import{_ as o,o as t,c as n,a5 as a}from"./chunks/framework.DJo0M80U.js";const p=JSON.parse('{"title":"计算题","description":"new 原型等 new new Foo().getName()面试题解析 // a. function Foo () \\\\{ getName function () \\\\{ console.log(1); \\\\} return this; \\\\} // b. Foo.getName fu。","frontmatter":{"title":"计算题","date":"2026-08-11T00:00:00.000Z","categories":["前端面试与实战"],"tags":["前端面试","算法","求职","教程","OneNote","前端知识复习"],"description":"new 原型等 new new Foo().getName()面试题解析 // a. function Foo () \\\\{ getName function () \\\\{ console.log(1); \\\\} return this; \\\\} // b. Foo.getName fu。","sidebarWeight":4,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/a-吊打面试官/复习大纲/JavaScript/计算题.md"},"headers":[],"relativePath":"posts/前端面试与实战/01-前端知识复习/JavaScript/计算题.md","filePath":"posts/前端面试与实战/01-前端知识复习/JavaScript/计算题.md"}'),g={name:"posts/前端面试与实战/01-前端知识复习/JavaScript/计算题.md"};function i(l,e,m,N,s,c){return t(),n("div",null,[...e[0]||(e[0]=[a('<div><h1 id="计算题" tabindex="-1">计算题 <a class="header-anchor" href="#计算题" aria-label="Permalink to &quot;计算题&quot;">​</a></h1><blockquote><p>本节目标：理解“计算题”的核心思路，并能把它用于实际开发或面试表达。</p></blockquote><ul><li>new 原型等</li></ul><p>new new Foo().getName()面试题解析 // a. function Foo () { getName = function () { console.log(1); } return this; } // b. Foo.getName = function () { console.log(2); } // c. Foo.prototype.getName = function () { console.log(3); } // d. var getName = function () { console.log(4); } // e. function getName () { console.log(5); } Foo.getName(); getName(); Foo().getName(); getName(); new Foo.getName(); new Foo().getName(); new new Foo().getName(); 解析：</p><ol><li><p>Foo.getName(); // 2 Foo为一个函数对象，对象都可以有属性，题目 b 处定义Foo的getName属性为函数，输出2</p></li><li><p>getName(); // 4 这里看d、e处，d为函数表达式，e为函数声明，两者区别在于变量提升，这两处可以等价于 var getName = undefined; // e处提升到顶部 getName = function () { console.log(5); } ... // d. 重新赋值 getName = function () { console.log(4); } // e. ... 可见函数声明的 5 会被后边函数表达式的 4 覆盖。</p></li><li><p>Foo().getName(); // 1 这里要看a处，在Foo内部将全局的getName重新赋值为 console.log(1) 的函数，执行Foo()返回 this，这个this指向window，Foo().getName() 即为window.getName()，输出 1。</p></li><li><p>getName(); // 1 上述3中，全局的getName已经被重新赋值，所以这里依然输出 1。</p></li><li><p>new Foo.getName(); // 2 这里等价于 new (Foo.getName())，先执行 Foo.getName()，输出 2，然后new一个实例；</p></li><li><p>new Foo().getName(); // 3 这里等价于 (new Foo()).getName(), 先new一个Foo的实例，再执行这个实例的getName方法，但是这个实例本身没有这个方法，所以去原型链__protot__上边找，实例.<strong>protot</strong> === Foo.prototype，所以输出 3。</p></li><li><p>new new Foo().getName(); // 3 这里等价于new (new Foo().getName())，如上述6，先输出 3，然后new 一个 new Foo().getName() 的实例。 补充： 关于上述 5中 new Foo.getName()先执行 Foo.getName()，而6中 new Foo().getName() 先执行 new Foo()，是因为： new Foo() 属于new（带参数列表） new Foo属于new（无参数列表） 无参数列表的优先级为18，而成员访问的优先级为19，高于无参数列表。因此new Foo.getName()先执行Foo.getName() 带参数列表的优先级为19，而成员访问的优先级也为19，按照运算符规则（同一优先级，按照从左向右的执行顺序），new Foo().getName()先执行new Foo()，再对new之后的实例进行成员访问.getName()操作。 这是js运算符的优先级链接，可查看每个运算符的优先级。</p></li></ol></div>',1)])])}const F=o(g,[["render",i]]);export{p as __pageData,F as default};
